head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30621";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — List

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_List", fn: function(){ return (!(String(((dma_pageContext.get("List") ?? "")) == null ? '' : ((dma_pageContext.get("List") ?? ""))).length === 0)); } }, { id: "tr_110", fn: function(){ return (!(String(((dma_pageContext.get("List") ?? "")) == null ? '' : ((dma_pageContext.get("List") ?? ""))).length === 0)); } }, { id: "tr_121", fn: function(){ return (!(String(((dma_pageContext.get("List") ?? "")) == null ? '' : ((dma_pageContext.get("List") ?? ""))).length === 0)); } }, { id: "if_List_2", fn: function(){ return ((String(((dma_pageContext.get("List") ?? "")) == null ? '' : ((dma_pageContext.get("List") ?? ""))).length === 0)); } }, { id: "tr_128", fn: function(){ return ((String(((dma_pageContext.get("List") ?? "")) == null ? '' : ((dma_pageContext.get("List") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_beforeName", fn: function () { return String((dma_pageContext.get("beforeName") ?? "")); } },
        { childId: "ipt_comCode", fn: function () { return String((dma_pageContext.get("comCode") ?? "")); } },
        { childId: "ipt_comName", fn: function () { return String((dma_pageContext.get("comName") ?? "")); } },
        { childId: "ipt_name", fn: function () { return String((dma_pageContext.get("name") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    if ('null' === 'end') {

    }
    const f = (document.form || { elements: [] });
    if ('null' === '' && 'null' === '') {
        setPeriod('12');
    }
    if ($c.util.getComponent("dma_submitReq").get("beforeName") !== '') {
        self.before.innerHTML = $c.util.getComponent("dma_submitReq").get("beforeName");
    }
};

/**
 * @method
 * @name initField
 * @description init Field 처리
 * @returns {void}
 * @hidden N
 */
scwin.initField = function () {
    const f = (document.form || { elements: [] });
    $c.util.getComponent("ipt_name").setValue("");
    f.birthday.value = "";
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30621.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_comCode_onclick
 * @description ipt_comCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_comCode_onclick = function(e){
    try {
        scwin.initField()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.ipt_comCode_onclick' }); }
};

/**
 * @method
 * @name ipt_comCode_onkeypress
 * @description ipt_comCode onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_comCode_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if (event.keyCode===13){scwin.searchCode('read'); return false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.ipt_comCode_onkeypress' }); }
};

/**
 * @method
 * @name btn_go_Stock_onclick
 * @description btn_go_Stock 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_go_Stock_onclick = function(e){
    try {
        go_Stock(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.btn_go_Stock_onclick' }); }
};

/**
 * @method
 * @name btn_searchPerson_onclick
 * @description btn_searchPerson 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchPerson_onclick = async function(e){
    try {
        await scwin.searchPerson()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30621.btn_searchPerson_onclick' }); }
};

/**
 * @method
 * @name rd_month_onclick
 * @description rd_month 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_month_onclick = function(e){
    try {
        setPeriod(3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.rd_month_onclick' }); }
};scwin.btn_searchCode_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.searchCode()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.btn_searchCode_onclick' }); }
};

/**
 * @method
 * @name btn_openDisclosure_onclick
 * @description btn_openDisclosure 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openDisclosure_onclick = function(e){
    try {
        openDisclosure('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30621.btn_openDisclosure_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submit = async function () {
    const sbmOptions = {
        id: "tx_submit",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchPerson
 * @description search Person 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchPerson = async function () {
    const sbmOptions = {
        id: "tx_searchPerson",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_searchPersonReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const f = (document.form || { elements: [] });
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "getThreePersonList");
    $c.util.getComponent("ipt_name").setValue(encodeURI($c.util.getComponent('ipt_name').getValue()));
    $c.util.getComponent("ipt_comName").setValue(encodeURI($c.util.getComponent('ipt_comName').getValue()));
    $c.util.getComponent("dma_submitReq").set("beforeName", encodeURI($c.util.getComponent("dma_submitReq").get("beforeName")));
    if ($c.num.isNumber($c.util.getComponent('ipt_comCode').getValue()) && $c.util.getComponent('ipt_comCode').getValue().length === 6) {
        $c.util.getComponent("ipt_comCode").setValue("A" + $c.util.getComponent('ipt_comCode').getValue());
    }
    if ((document.form || { elements: [] }).regcncl[1].checked) {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    } else {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    }
    await scwin.tx_submit();

};

/**
 * @method
 * @name searchPerson
 * @description search Person 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchPerson = async function () {
    let chgList;
    $c.util.getComponent("ipt_name").setValue(encodeURI($c.util.getComponent('ipt_name').getValue()));
    const strOptions = "width=430, height=300, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    chgList = $c.win.openPopup("", String((typeof strOptions !== 'undefined' ? strOptions : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }, { id: '' }) : { id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }), {});
    (document.form2 || { elements: [] }).target = "chgList";
    await scwin.tx_searchPerson();
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @param {*} searchValue searchValue
 * @returns {void}
 * @hidden N
 */
scwin.searchCode = function (searchValue) {
    let iCount = 0;
    arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (regcncl === "1") {
                    arrCode[iCount] = jr[j].jcode;
                    arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        arrCode[iCount] = jr[j].jcode;
                        arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    setSelectBox();
};
